#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
named FW_GROUP_IP fws_dp-blocked-ranges && fail 'an IP group named fws_dp-blocked-ranges exists; nothing was written'
named FW_GROUP_PORT fws_svc-mail && fail 'a port group named fws_svc-mail exists; nothing was written'
named FW_GROUP_IP fws_dp-partner-mail && fail 'an IP group named fws_dp-partner-mail exists; nothing was written'
named FW_GROUP_PORT fws_svc-voice && fail 'a port group named fws_svc-voice exists; nothing was written'
named FW_GROUP_IP fws_dp-voice-provider && fail 'an IP group named fws_dp-voice-provider exists; nothing was written'
named FW_GROUP_IP fws_app-ssh-jump && fail 'an IP group named fws_app-ssh-jump exists; nothing was written'
named FW_GROUP_IP fws_app-rdp-gw && fail 'an IP group named fws_app-rdp-gw exists; nothing was written'
named FW_GROUP_PORT fws_app-git && fail 'a port group named fws_app-git exists; nothing was written'
named FW_GROUP_IP fws_Not_from_the_server_networks && fail 'an IP group named fws_Not_from_the_server_networks exists; nothing was written'
named FW_GROUP_IP fws_dp-time && fail 'an IP group named fws_dp-time exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dp-blocked-ranges --set .COMMENT 'FWShift: dp-blocked-ranges'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.128/26
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.200
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dp-partner-mail --set .COMMENT 'FWShift: dp-partner-mail'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.25-198.51.100.26
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dp-voice-provider --set .COMMENT 'FWShift: dp-voice-provider'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.0/26
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_app-ssh-jump --set .COMMENT 'FWShift: app-ssh-jump'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.10/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_app-rdp-gw --set .COMMENT 'FWShift: app-rdp-gw'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.40
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Not_from_the_server_networks --set .COMMENT 'FWShift: not 10.20.10.0/24, 10.20.11.0/25'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.20.9.255
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.11.128-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dp-time --set .COMMENT 'FWShift: dp-time'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.123
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_svc-mail --set .COMMENT 'FWShift: svc-mail'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 587
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 993
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_svc-voice --set .COMMENT 'FWShift: svc-voice'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 5060
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 10000-20000
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_app-git --set .COMMENT 'FWShift: app-git'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 22
gc --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 9418
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
